@Override public void onUserAction(UserActionMsg msg){
  final String user=msg.getSource().getNick();
  String text;
  try {
    text = Utils.formatAction(Utils.parse(msg.getText()), user);
  } catch (IndexOutOfBoundsException e) {
    // Handle the exception, e.g., log an error, use a default text, or rethrow
    text = "Default action text";
  }
  MessageIrcImpl message=new MessageIrcImpl(text, OperationSetBasicInstantMessaging.HTML_MIME_TYPE, OperationSetBasicInstantMessaging.DEFAULT_MIME_ENCODING, "");
  Contact from;
  try {
    from = IrcStack.this.provider.getPersistentPresence().findContactByID(user);
  } catch (NoSuchElementException e) {
    // Handle the exception, e.g., log an error, use a default contact, or rethrow
    from = IrcStack.this.provider.getPersistentPresence().getDefaultContact();
  }
  IrcStack.this.provider.getBasicInstantMessaging().fireMessageReceived(message, from);
}
